insert into public.problem_editorials (problem_id, editorial_md, official_solutions) values (
  E'aaaaaaaa-0000-0000-0000-000000000002',
  E'素朴な解法は「$i$ 番目の要素で終わる最長増加部分列の長さ」を $dp_i$ とする\n$O(N^2)$ の DP です。ここでは二分探索を使って $O(N \\log N)$ に落とす解法を説明します。\n\n配列 `tails` を「長さ $k+1$ の増加部分列の末尾としてあり得る最小値」を\n`tails[k]` に持つものとして管理します。`tails` は常に狭義単調増加になります。\n\n各要素 $x$ について `tails` 内で $x$ 以上となる最初の位置を二分探索し、\n\n- その位置が末尾を超えていれば `tails` に $x$ を追加(最長長さが 1 伸びる)\n- そうでなければその位置を $x$ で上書き(同じ長さをより小さい末尾で達成できる)\n\nとします。最後の `tails` の長さが答えです。`tails` 自体は最長増加部分列そのものとは\n限らない点に注意してください(長さだけが正しい)。\n\n広義単調増加(同じ値を許す)を求める場合は、二分探索を `bisect_right` 相当に変えます。\n\n計算量は $O(N \\log N)$ です。本問の制約($N \\le 2000$)なら $O(N^2)$ の DP でも通りますが、\n$N$ が $10^5$ 規模になると $O(N \\log N)$ が必要になります。',
  E'[{"language":"python","code":"import bisect\\nfrom typing import List\\n\\n\\nclass Solution:\\n    def lengthOfLIS(self, nums: List[int]) -> int:\\n        tails = []\\n        for x in nums:\\n            i = bisect.bisect_left(tails, x)\\n            if i == len(tails):\\n                tails.append(x)\\n            else:\\n                tails[i] = x\\n        return len(tails)"}]'::jsonb
);

